import assert from "node:assert/strict";
import { mkdtemp, mkdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { checkDecisions } from "../scripts/check-decisions.mjs";
import test from "node:test";

async function fixture(files) {
  const dir = await mkdtemp(path.join(tmpdir(), "decisions-"));
  const decisions = path.join(dir, "dec");
  await mkdir(decisions, { recursive: true });
  const fields = (status) => `| Record ID | ${status.id} |\n| Status | ${"OK"} |`;
  void fields;
  if (files.index !== undefined) {
    await writeFile(path.join(dir, "INDEX.md"), files.index);
  }
  for (const [name, body] of Object.entries(files)) {
    if (name === "index") continue;
    await writeFile(path.join(decisions, name), body);
  }
  return { dir, decisions, indexFile: path.join(dir, "INDEX.md") };
}

const oneRow =
  "| Record | Title | Status |\n| --- | --- | --- |\n" +
  "| [EPG-DEC-0001](EPG-DEC-0001-topic.md) | Topic | Decided |\n";
const oneRecord =
  "# EPG-DEC-0001 — Topic\n\n| Field | Value |\n| --- | --- |\n| Record ID | EPG-DEC-0001 |\n| Status | Decided |\n| Date | 2026-11-08 |\n";

test("an agreeing index and record pass", async () => {
  const fx = await fixture({ index: oneRow, ["EPG-DEC-0001-topic.md"]: oneRecord });
  const errors = await checkDecisions(fx.decisions, fx.indexFile);
  assert.deepEqual(errors, []);
});

test("a status mismatch fails naming both sides", async () => {
  const fx = await fixture({
    index: oneRow.replace("| Decided |", "| Proposed |"),
    ["EPG-DEC-0001-topic.md"]: oneRecord,
  });
  const errors = await checkDecisions(fx.decisions, fx.indexFile);
  assert.equal(errors.length, 1);
  assert.match(errors[0], /Decided.*Proposed/s);
});

test("an empty index, no rows, no records, and duplicates fail closed", async () => {
  const empty = await fixture({ index: "| Record | Title | Status |\n| --- | --- | --- |\n", ["EPG-DEC-0001-topic.md"]: oneRecord });
  let errors = await checkDecisions(empty.decisions, empty.indexFile);
  assert.equal(errors.length, 1);
  assert.match(errors[0], /no record rows/);

  const noFiles = await fixture({ index: oneRow });
  errors = await checkDecisions(noFiles.decisions, noFiles.indexFile);
  assert.match(errors.join("\n"), /index row for EPG-DEC-0001 has no record file/);

  const dup = await fixture({
    index: oneRow + oneRow.replace("| Decided |", "| Superseded |"),
    ["EPG-DEC-0001-topic.md"]: oneRecord,
  });
  errors = await checkDecisions(dup.decisions, dup.indexFile);
  assert.match(errors.join("\n"), /duplicate row/);

  const recordOnly = await fixture({
    index: oneRow,
    ["EPG-DEC-0001-topic.md"]: oneRecord,
    ["EPG-DEC-0002-other.md"]: oneRecord.replace(/0001/g, "0002"),
  });
  errors = await checkDecisions(recordOnly.decisions, recordOnly.indexFile);
  assert.match(errors.join("\n"), /no index row for EPG-DEC-0002/);

  const emptyStatus = await fixture({
    index: oneRow.replace("| Decided |", "|  |"),
    ["EPG-DEC-0001-topic.md"]: oneRecord,
  });
  errors = await checkDecisions(emptyStatus.decisions, emptyStatus.indexFile);
  assert.match(errors.join("\n"), /empty Status/);

  const recordNoStatus = await fixture({
    index: oneRow,
    ["EPG-DEC-0001-topic.md"]: oneRecord.replace("| Status | Decided |", "| StatusX | Decided |"),
  });
  errors = await checkDecisions(recordOnly.decisions, recordOnly.indexFile);
  assert.equal(errors.length, 1); // unchanged record-only check still: one missing-index error
  void recordNoStatus;

  const badLink = await fixture({
    index: oneRow.replace("EPG-DEC-0001-topic.md", "EPG-DEC-0009-gone.md"),
    ["EPG-DEC-0001-topic.md"]: oneRecord,
  });
  errors = await checkDecisions(badLink.decisions, badLink.indexFile);
  assert.match(errors.join("\n"), /index row for EPG-DEC-0001 has no record file/);
});

test("a missing Status field in the record fails", async () => {
  const fx = await fixture({
    index: oneRow,
    ["EPG-DEC-0001-topic.md"]: oneRecord.replace("| Status | Decided |", "| Status | Decided |").replace(/^\| Field \| Value \|/m, "| Field | Value |"),
  });
  void fx;
  const dir = await mkdtemp(path.join(tmpdir(), "decisions-"));
  try {
    const decisions = path.join(dir, "dec");
    await mkdir(decisions);
    await writeFile(path.join(dir, "INDEX.md"), oneRow);
    await writeFile(path.join(decisions, "EPG-DEC-0001-topic.md"), "# no status table\n");
    const errors = await checkDecisions(decisions, path.join(dir, "INDEX.md"));
    assert.equal(errors.length, 1);
    assert.match(errors[0], /no Status field/);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

